import React, { useState } from "react";
import WeatherCard from "./components/WeatherCard";
import SearchBar from "./components/SearchBar";
import "./App.css";

function App() {
  const [weather, setWeather] = useState(null);

  const fetchWeather = async (city) => {
    try {
      const apiKey = "73f099dc85c1bec48f0cb652b09c91da"; // a tua key
      const res = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}&units=metric&lang=pt`
      );
      const data = await res.json();
      if (data.cod === 200) {
        setWeather(data);
      } else {
        alert("Cidade não encontrada!");
      }
    } catch (err) {
      console.error(err);
    }
  };

  // gerar folhas: metade vêm da árvore esquerda, metade da direita
  const leafCount = 24;
  const leaves = Array.from({ length: leafCount }).map((_, i) => {
    const fromLeftTree = i % 2 === 0; // alterna
    const leftRange = fromLeftTree ? [5, 28] : [65, 92]; // intervalo em vw
    const left = leftRange[0] + Math.random() * (leftRange[1] - leftRange[0]);
    const top = 8 + Math.random() * 10; // início perto do topo das copas (em vh)
    const duration = 5 + Math.random() * 6; // 5s - 11s
    const delay = Math.random() * 6; // 0s - 6s
    const size = 18 + Math.random() * 16; // px
    const colorClass = ["leaf--orange", "leaf--red", "leaf--yellow"][Math.floor(Math.random() * 3)];
    // amplitude horizontal para dada folha
    const sway = 30 + Math.random() * 40; // px
    return {
      key: `leaf-${i}`,
      left,
      top,
      duration,
      delay,
      size,
      colorClass,
      sway,
    };
  });

  return (
    <div className="App">
      {/* Árvores no fundo */}
      <div className="trees">
        <div className="tree left">
          <div className="crown"></div>
          <div className="trunk"></div>
        </div>

        <div className="tree right">
          <div className="crown"></div>
          <div className="trunk"></div>
        </div>
      </div>

      {/* Folhas animadas a cair da zona das árvores */}
      {leaves.map((leaf) => (
        <div
          key={leaf.key}
          className={`leaf ${leaf.colorClass}`}
          style={{
            left: `${leaf.left}vw`,
            top: `${leaf.top}vh`,
            width: `${leaf.size}px`,
            height: `${leaf.size * 0.7}px`,
            animationDuration: `${leaf.duration}s`,
            animationDelay: `${leaf.delay}s`,
            // passamos a amplitude de oscilação via custom property
            ["--sway"]: `${leaf.sway}px`,
          }}
        />
      ))}

      <div className="app-content">
        <h1>Weather App 🌤️</h1>
        <SearchBar onSearch={fetchWeather} />
        {weather && <WeatherCard weather={weather} />}
      </div>
    </div>
  );
}

export default App;
